SELECT p.first_name, p.last_name, r.ranking, p.player_id FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY p.first_name, p.last_name LIMIT 100;
SELECT p.first_name, p.last_name FROM players p JOIN matches m ON p.player_id = m.loser_id JOIN rankings r ON m.match_num = r.ranking_date ORDER BY p.birth_date DESC, r.ranking DESC;
SELECT p.first_name, p.last_name, p.birth_date FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY p.birth_date ASC
SELECT p.first_name, p.country_code, p.player_id FROM players p JOIN matches m ON p.player_id = m.loser_id JOIN rankings r ON p.player_id = r.player_id WHERE m.tourney_id = (SELECT tourney_id FROM matches WHERE tourney_name = 'Most Tours') ORDER BY p.rankings_points DESC LIMIT 1;
SELECT p.first_name, p.country_code FROM players p JOIN matches m ON p.player_id = m.loser_id GROUP BY p.player_id ORDER BY p.country_code DESC LIMIT 1;
SELECT year, COUNT(*) AS match_count FROM matches GROUP BY year ORDER BY match_count DESC LIMIT 1
SELECT year, COUNT(*) AS num_matches FROM matches GROUP BY year ORDER BY num_matches DESC;
