SELECT p.first_name, p.last_name, m.rank_points, m.best_of FROM players p JOIN matches m ON p.player_id = m.loser_id WHERE m.rank_points = (SELECT MAX(rank_points) FROM rankings r) ORDER BY p.first_name, p.last_name
SELECT p.first_name, p.last_name, p.hand, p.birth_date, p.country_code, m.best_of, m.draw_size, m.loser_age, m.loser_entry, m.loser_hand, m.loser_ht, m.loser_id, m.loser_name, m.loser_rank, m.loser_rank_points, m.loser_seed, m.match_num, m.minutes, m.round, m.score, m.surface, m.tourney_date, m.tourney_id, m.tourney_level, m.tourney_name, p.winner_age, p.winner_entry, p.winner_hand, p.winner_ht, p.winner_id, p.winner_name, p.winner_rank, p.winner_rank_points, p.winner_seed, p.year FROM players p JOIN matches m ON p.player_id = m.loser_id WHERE m.tourney_id = (SELECT tourney_id FROM rankings r WHERE r.ranking_points = (SELECT MAX(ranking_points) FROM rankings r)) AND p.country_code = 'AU'
SELECT p.first_name, p.last_name, r.ranking_points, r.ranking, r.player_id FROM players p JOIN rankings r ON p.player_id = r.player_id WHERE r.tournament_name = 'Australian Open' AND r.ranking_points = (SELECT MAX(ranking_points) FROM rankings r2 WHERE r2.tournament_name = 'Australian Open') AND r.ranking = (SELECT MAX(ranking) FROM rankings r2 WHERE r2.tournament_name = 'Australian Open')
SELECT p.first_name, p.last_name, p.hand, p.birth_date, p.country_code, m.minutes, m.round, m.score, m.surface, m.tourney_date, m.tourney_id, m.tourney_level, m.tourney_name, m.winner_age, m.winner_entry, m.winner_hand, m.winner_ht, m.winner_id, m.winner_ioc, m.winner_name, m.winner_rank, m.winner_rank_points, m.winner_seed, m.year FROM players p JOIN matches m ON m.winner_id = p.player_id ORDER BY m.minutes DESC;
SELECT winner_name, loser_name FROM matches INNER JOIN players ON matches.winner_id = players.player_id AND matches.loser_id = players.player_id WHERE matches.best_of = (SELECT MAX(best_of) FROM matches) GROUP BY winner_name, loser_name
SELECT players.first_name, AVG(matches.loser_rank) AS average_ranking FROM players INNER JOIN matches ON players.player_id = matches.loser_id;
SELECT p.first_name, AVG(r.ranking_points) AS average_rankings FROM players p JOIN rankings r ON p.player_id = r.player_id GROUP BY p.first_name ORDER BY p.first_name
SELECT players.first_name, players.last_name, SUM(rankings.rank_points) AS total_ranking_points FROM players JOIN rankings ON players.player_id = rankings.player_id GROUP BY players.first_name, players.last_name
SELECT players.first_name, players.last_name, rankings.ranking_points FROM players INNER JOIN rankings ON players.player_id = rankings.player_id;
SELECT COUNT(DISTINCT players.country_code) FROM players;
