SELECT country_code FROM players JOIN rankings ON players.player_id = rankings.player_id ORDER BY ranking_points DESC LIMIT 1;
SELECT country_code FROM players WHERE player_id IN (SELECT player_id FROM matches WHERE winner_id IN (SELECT player_id FROM rankings WHERE ranking_points = (SELECT MAX(ranking_points) FROM rankings)) GROUP BY player_id) ORDER BY country_code DESC;
SELECT player_id, country_code FROM players JOIN matches ON players.player_id = matches.loser_id WHERE matches.round = '2022' AND matches.minutes > 50000
SELECT country_code FROM players JOIN matches ON players.player_id = matches.loser_id GROUP BY players.country_code HAVING COUNT(players.player_id) > 50
SELECT COUNT(DISTINCT rankings.ranking_date) AS total_tours FROM rankings INNER JOIN players ON rankings.player_id = players.player_id;
