SELECT year, COUNT(*) AS total_matches FROM matches GROUP BY year
SELECT p.first_name, p.rankings.ranking FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY p.rankings.ranking ASC LIMIT 3;
SELECT p.first_name, p.last_name, r.ranking FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY r.ranking ASC LIMIT 3;
SELECT COUNT(DISTINCT players.player_id) FROM players JOIN matches ON matches.winner_id = players.player_id AND players.hand = 'L'
SELECT COUNT(DISTINCT players.player_id) FROM players INNER JOIN matches ON players.player_id = matches.winner_id;
SELECT players.first_name, players.birth_date, matches.winner_rank_points FROM players JOIN matches ON players.player_id = matches.winner_id WHERE matches.loser_rank_points IS NULL ORDER BY matches.winner_rank_points DESC LIMIT 1
