SELECT orchestra.Orchestra, conductor.Name, orchestra.Year_of_Founded FROM conductor INNER JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID ORDER BY orchestra.Year_of_Founded ASC;
