SELECT conductor.Name, orchestra.Orchestra, conductor.Conductor_ID, orchestra.Record_Company, orchestra.Year_of_Founded, orchestra.Major_Record_Format FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID ORDER BY orchestra.Year_of_Founded DESC LIMIT 1;
