SELECT p.Type, o.Orchestra, o.Conductor_ID, o.Record_Company, o.Year_of_Founded, o.Major_Record_Format FROM performance p JOIN orchestra o ON p.Orchestra_ID = o.Orchestra_ID WHERE p.Weekly_rank > 0 AND p.Share > 0 AND p.Type = 'Non-first show' AND o.Record_Company IS NOT NULL;
