SELECT o.first_name FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Professionals p ON d.professional_id = p.professional_id JOIN Treatments t ON d.dog_id = t.dog_id WHERE p.role_code = 'Professional' OR p.role_code = 'Owner' AND d.name NOT IN ('dog_name') AND o.first_name != 'dog_name'
