SELECT p.professional_id, o.street, o.cell_number, p.first_name, p.last_name, o.email_address, o.home_phone, o.cell_number FROM Professionals p JOIN Owners o ON p.owner_id = o.owner_id WHERE p.role_code = 'Professional' AND o.abandoned_yn = 'No' AND p.first_name != '' AND p.last_name != '' AND o.street != '' AND o.cell_number != '' AND o.email_address != '' AND o.home_phone != '' ORDER BY p.professional_id
SELECT p.professional_id, p.first_name, p.last_name, t.treatment_type_code, t.date_of_treatment, t.cost_of_treatment FROM Professionals p JOIN Treatments t ON p.professional_id = t.professional_id WHERE t.treatment_type_code = (SELECT treatment_type_code FROM Treatment_Types) AND t.treatment_type_code = (SELECT treatment_type_code FROM Treatment_Types) AND t.dog_id = (SELECT dog_id FROM Dogs) AND t.treatment_type_code = (SELECT treatment_type_code FROM Treatment_Types) AND t.date_of_treatment IS NOT NULL ORDER BY p.professional_id;
SELECT breed_name FROM Breeds WHERE breed_code IN (SELECT Dogs.breed_code FROM Dogs JOIN Treatments ON Dogs.dog_id = Treatments.dog_id JOIN Professionals ON Treatments.professional_id = Professionals.professional_id JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code GROUP BY Treatments.treatment_type_code ORDER BY Treatments.cost_of_treatment DESC LIMIT 1)
SELECT breed_name FROM Breeds WHERE breed_code IN (SELECT Dogs.breed_code FROM Dogs JOIN Treatments ON Dogs.dog_id = Treatments.dog_id JOIN Professionals ON Treatments.professional_id = Professionals.professional_id GROUP BY Professionals.professional_id ORDER BY COUNT(Dogs.abandoned_yn) DESC LIMIT 1)
SELECT o.owner_id, o.last_name, t.cost_of_treatment AS total_cost FROM Owners o JOIN Treatments t ON o.owner_id = t.dog_id GROUP BY o.owner_id ORDER BY total_cost DESC LIMIT 1;
SELECT Dogs.owner_id, Owners.last_name FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id ORDER BY Charges.charge_amount DESC LIMIT 1;
SELECT treatment_type_description, cost_of_treatment FROM Treatments INNER JOIN Charges ON Treatments.treatment_type_code = Charges.charge_type_id WHERE cost_of_treatment = (SELECT MIN(cost_of_treatment) FROM Treatments)
SELECT treatment_type_description FROM Treatment_Types WHERE cost_of_treatment < (SELECT cost_of_treatment FROM Treatment_Types ORDER BY cost_of_treatment LIMIT 1)
SELECT o.owner_id, o.zip_code, o.first_name, o.last_name, o.street, o.city, o.state, o.zip_code, o.email_address, o.home_phone, o.cell_number, d.owner_id, d.zip_code, d.breed_code, d.size_code, d.name, d.age, d.date_of_birth, d.gender, d.weight, d.date_arrived, d.date_adopted, d.date_departed FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Treatments t ON d.dog_id = t.dog_id JOIN Sizes s ON d.size_code = s.size_code JOIN Breeds b ON d.breed_code = b.breed_code WHERE d.owner_id = (SELECT o.owner_id FROM Owners o WHERE o.zip_code = (SELECT MAX(zip_code) FROM Owners)) ORDER BY d.owner_id, d.zip_code LIMIT 1;
SELECT Owners.owner_id, Dogs.zip_code FROM Owners INNER JOIN Dogs ON Dogs.owner_id = Owners.owner_id WHERE Dogs.date_departed IS NULL OR Dogs.date_departed IS NULL;
SELECT Professionals.professional_id, Professionals.first_name, Professionals.last_name FROM Professionals JOIN Dogs ON Dogs.owner_id = Professionals.owner_id JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code JOIN Charges ON Charges.charge_id = Treatments.cost_of_treatment JOIN Sizes ON Dogs.size_code = Sizes.size_code JOIN Breeds ON Dogs.breed_code = Breeds.breed_code WHERE Professionals.role_code = 'Professional' AND Treatments.dog_id = Dogs.dog_id AND Treatments.treatment_type_code = Treatment_Types.treatment_type_code AND Treatments.cost_of_treatment > 0;
SELECT o.owner_id, o.first_name, o.last_name, o.street, o.city, o.state, o.zip_code, o.email_address, t.home_phone, t.cell_number FROM Owners o JOIN Treatments t ON o.owner_id = t.professional_id JOIN Dogs d ON t.dog_id = d.id JOIN Treatment_Types t1 ON t.treatment_type_code = t1.treatment_type_code WHERE t.treatment_type_code IN (1, 2) AND d.abandoned_yn = 'N' AND o.street IS NOT NULL;
SELECT p.first_name, p.last_name, p.email_address, p.home_phone, p.cell_number, t.cost_of_treatment FROM Professionals p JOIN Treatments t ON p.professional_id = t.professional_id WHERE t.cost_of_treatment < (SELECT AVG(cost_of_treatment) FROM Charges);
SELECT p.first_name, p.last_name FROM Professionals p JOIN Treatments t ON p.professional_id = t.professional_id JOIN Dogs d ON t.dog_id = d.dog_id JOIN Sizes s ON d.size_code = s.size_code JOIN Breeds b ON d.breed_code = b.breed_code WHERE t.cost_of_treatment < (SELECT AVG(cost_of_treatment) FROM Charges c WHERE c.charge_id = t.charge_id)
SELECT Dogs.date_of_birth, Professionals.first_name, Professionals.last_name FROM Dogs JOIN Professionals ON Dogs.owner_id = Professionals.owner_id JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code JOIN Dogs ON Treatments.dog_id = Dogs.dog_id JOIN Professionals ON Treatments.professional_id = Professionals.professional_id;
SELECT Dogs.name, Professionals.first_name, Professionals.last_name FROM Dogs JOIN Professionals ON Dogs.owner_id = Professionals.owner_id WHERE Dogs.date_of_birth IS NOT NULL;
SELECT Dogs.name, Treatment_Types.treatment_type_description, Charges.charge_amount FROM Dogs INNER JOIN Charges ON Dogs.owner_id = Charges.charge_id INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code;
SELECT Dogs.name, Treatment_Types.treatment_type_description, Charges.charge_amount FROM Dogs INNER JOIN Charges ON Dogs.owner_id = Charges.charge_id INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code;
SELECT o.first_name, o.last_name, d.size_code, d.size_description, d.name, d.age, d.date_of_birth, d.gender, d.weight, d.date_arrived, d.date_departed FROM Dogs d JOIN Owners o ON d.owner_id = o.owner_id JOIN Sizes s ON d.size_code = s.size_code;
SELECT Dogs.name, Dogs.weight FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id;
SELECT Dogs.name, Owners.first_name, Owners.last_name, Dogs.owner_id, Dogs.breed_code, Dogs.size_code FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id;
SELECT Dogs.name, Owners.first_name, Owners.last_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id;
SELECT Dogs.name, Treatments.date_of_treatment FROM Dogs INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id WHERE Treatments.treatment_type_code = 'rare' AND Treatments.cost_of_treatment IS NULL;
SELECT Dogs.name, Treatment_Types.treatment_type_description AS treatment_type, Treatments.date_of_treatment AS date_of_treatment FROM Dogs JOIN Treatment_Types ON Dogs.breed_code = Treatment_Types.treatment_type_code JOIN Treatments ON Treatments.dog_id = Dogs.dog_id;
SELECT Dogs.owner_id, Dogs.name, Owners.first_name, Owners.last_name FROM Owners INNER JOIN Dogs ON Owners.owner_id = Dogs.owner_id WHERE Owners.state = 'VA' GROUP BY Owners.first_name, Owners.last_name
SELECT Dogs.name, Owners.first_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Owners.state = 'VA' AND Dogs.abandoned_yn = 'N' AND Dogs.date_of_birth IS NULL;
SELECT d.date_departed, t.date_of_treatment FROM Dogs d JOIN Treatments t ON d.dog_id = t.dog_id;
SELECT Dogs.date_departed, Dogs.date_of_birth, Dogs.name, Dogs.gender, Dogs.weight, Dogs.date_arrived, Dogs.date_adopted, Professionals.first_name, Professionals.last_name, Professionals.email_address, Professionals.home_phone, Professionals.cell_number, Treatment_Types.treatment_type_description FROM Dogs JOIN Professionals ON Dogs.owner_id = Professionals.owner_id JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code JOIN Treatments ON Treatments.dog_id = Dogs.dog_id;
SELECT Dogs.owner_id, Owners.last_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Dogs.age = (SELECT MIN(age) FROM Dogs)
SELECT Owners.last_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Dogs.age = (SELECT MIN(age) FROM Dogs)
SELECT o.email_address FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Treatments t ON d.dog_id = t.dog_id JOIN Professionals p ON p.professional_id = t.professional_id WHERE o.state = 'HI' OR o.state = 'WI' AND d.state = 'HI' OR d.state = 'WI';
SELECT email_address FROM Owners JOIN Professionals ON Owners.owner_id = Professionals.owner_id WHERE Professionals.state IN ('HI', 'WI')
SELECT Dogs.date_arrived, Dogs.date_departed FROM Dogs INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id;
SELECT Dogs.date_departed, Dogs.date_arrived FROM Dogs WHERE Dogs.abandoned_yn = 'A' AND Dogs.date_departed IS NULL;
SELECT COUNT(DISTINCT Dogs.dog_id) FROM Dogs;
SELECT COUNT(DISTINCT Dogs.dog_id) FROM Dogs;
SELECT COUNT(DISTINCT Professionals.professional_id) FROM Professionals JOIN Dogs ON Professionals.owner_id = Dogs.owner_id;
SELECT COUNT(DISTINCT Professionals.professional_id) FROM Professionals INNER JOIN Dogs ON Dogs.owner_id = Professionals.owner_id;
