SELECT Owners.first_name, Owners.last_name FROM Owners INNER JOIN Dogs ON Dogs.owner_id = Owners.owner_id WHERE Dogs.state LIKE '%North%';
SELECT COUNT(DISTINCT Dogs.dog_id) FROM Dogs WHERE Dogs.abandoned_yn = 'Y' AND Dogs.age < (SELECT AVG(Dogs.age) FROM Dogs)
