SELECT cost_of_treatment FROM Treatments WHERE date_of_treatment = (SELECT MAX(date_of_treatment) FROM Treatments)
SELECT MAX(cost_of_treatment) FROM Treatments;
SELECT COUNT(DISTINCT Dogs.dog_id) FROM Dogs WHERE Dogs.abandoned_yn = 'Y' AND Dogs.date_departed IS NULL;
SELECT COUNT(DISTINCT Dogs.dog_id) FROM Dogs;
SELECT COUNT(DISTINCT Owners.owner_id) FROM Owners JOIN Dogs ON Dogs.owner_id = Owners.owner_id WHERE Dogs.abandoned_yn = 'N' AND Dogs.date_departed IS NULL;
SELECT COUNT(DISTINCT Owners.owner_id) FROM Owners WHERE Owners.owner_id NOT IN (SELECT Dogs.owner_id FROM Dogs WHERE Dogs.abandoned_yn = 'Y') AND Dogs.owner_id IS NULL;
SELECT COUNT(DISTINCT Professionals.professional_id) FROM Professionals INNER JOIN Treatments ON Treatments.professional_id = Professionals.professional_id INNER JOIN Dogs ON Treatments.dog_id = Dogs.dog_id WHERE Dogs.abandoned_yn = 'N' AND Dogs.date_departed IS NULL;
SELECT COUNT(*) FROM Professionals WHERE role_code = 'Professional' AND (NOT EXISTS (SELECT 1 FROM Dogs WHERE abandoned_yn = 'Y' AND Dogs.dog_id = Professionals.professional_id))
SELECT Dogs.name, Dogs.age, Dogs.weight, Dogs.abandoned_yn FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id;
SELECT Dogs.name, Dogs.age, Dogs.weight, Dogs.abandoned_yn FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id;
SELECT AVG(Dogs.age) FROM Dogs;
SELECT AVG(Dogs.age) FROM Dogs;
SELECT Dogs.age AS age FROM Dogs;
SELECT Dogs.age FROM Dogs ORDER BY Dogs.age DESC LIMIT 1
SELECT charge_type, charge_amount FROM Charges;
SELECT charge_type, charge_amount FROM Charges;
SELECT MAX(charge_amount) AS most_expensive_charge_cost FROM Charges;
SELECT charge_amount FROM Charges ORDER BY charge_amount DESC LIMIT 1
SELECT o.first_name, o.last_name, d.name, p.email_address, p.home_phone, p.cell_number FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Professionals p ON d.owner_id = p.professional_id;
SELECT Professionals.first_name, Professionals.last_name, Professionals.email_address, Professionals.home_phone, Professionals.cell_number FROM Professionals JOIN Dogs ON Dogs.owner_id = Professionals.owner_id;
SELECT Dogs.breed_code, Dogs.size_code, Treatments.treatment_type_code, Treatments.cost_of_treatment FROM Dogs INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id;
SELECT DISTINCT breeds.breed_name, sizes.size_description FROM Breeds INNER JOIN Sizes ON Dogs.size_code = Sizes.size_code INNER JOIN Treatments ON Treatments.dog_id = Dogs.dog_id INNER JOIN Professionals ON Treatments.professional_id = Professionals.professional_id INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code GROUP BY breeds.breed_name, sizes.size_description;
SELECT Professionals.first_name, Professionals.last_name, Treatment_Types.treatment_type_description AS treatment_type_description FROM Professionals INNER JOIN Treatments ON Professionals.professional_id = Treatments.professional_id INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code JOIN Dogs ON Treatments.dog_id = Dogs.dog_id JOIN Sizes ON Dogs.size_code = Sizes.size_code JOIN Breeds ON Dogs.breed_code = Breeds.breed_code;
SELECT Professionals.first_name, Professionals.last_name, Treatments.date_of_treatment, Treatments.cost_of_treatment FROM Professionals JOIN Treatments ON Professionals.professional_id = Treatments.professional_id WHERE Treatments.treatment_type_code = Treatment_Types.treatment_type_code;
